from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.five_minute_closes = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bars = []
        self.last_minute_end = None
        self.minute_bar_date = None

        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_price = None
        self.no_entry_date = None
        self.equity_liquidation_order_id = None

    def OnData(self, data: Slice):
        self._handle_unexpected_spy_position()
        self._handle_expiration_safety()
        self._evaluate_option_exit(data)
        self._update_five_minute_bar(data)

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.held_contract = order_event.Symbol
                self.entry_order_id = None
                self.Debug(
                    f"ENTRY filled {self.held_contract} at {self.entry_price:.2f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug(f"ENTRY not filled: {order_event.Status}")
                self.entry_order_id = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"EXIT filled {order_event.Symbol} at {order_event.FillPrice:.2f}")
                self.exit_order_id = None
                self.held_contract = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_order_id = None

        if order_event.OrderId == self.equity_liquidation_order_id:
            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.equity_liquidation_order_id = None

    def _update_five_minute_bar(self, data: Slice):
        if self.spy not in data.Bars:
            return

        minute_bar = data.Bars[self.spy]
        end_time = minute_bar.EndTime
        current_date = end_time.date()

        if self.minute_bar_date != current_date:
            self.minute_bar_date = current_date
            self.minute_bars = []
            self.last_minute_end = None

        session_start = time(9, 31)
        session_end = time(16, 0)
        end_clock = end_time.time()

        if end_clock < session_start or end_clock > session_end:
            return

        minutes_after_open = end_time.hour * 60 + end_time.minute - (9 * 60 + 30)
        slot = minutes_after_open % 5

        if not self.minute_bars:
            if slot != 1:
                return
        elif end_time != self.last_minute_end + timedelta(minutes=1):
            self.minute_bars = []
            if slot != 1:
                self.last_minute_end = end_time
                return

        self.minute_bars.append(minute_bar)
        self.last_minute_end = end_time

        if len(self.minute_bars) != 5:
            return

        if end_time.minute % 5 != 0:
            self.minute_bars = []
            return

        close = self.minute_bars[-1].Close
        bar_end = self.minute_bars[-1].EndTime
        self.minute_bars = []

        self.five_minute_closes.Add(close)
        if not self.five_minute_closes.IsReady:
            return

        fast = sum(self.five_minute_closes[i] for i in range(5)) / 5.0
        slow = sum(self.five_minute_closes[i] for i in range(20)) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish_cross:
            return

        if time(9, 45) <= bar_end.time() <= time(14, 30):
            self._try_enter_from_chain(data)

    def _try_enter_from_chain(self, data: Slice):
        if self.no_entry_date == self.Time.date():
            return

        if self.entry_order_id is not None or self.exit_order_id is not None:
            return

        if self._has_option_holding():
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("ENTRY skipped: no option chain")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("ENTRY skipped: invalid SPY price")
            return

        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - self.Time.date()).days >= 7
        })

        if not eligible_expirations:
            self.Debug("ENTRY skipped: no expiration at least 7 calendar days away")
            return

        expiration = eligible_expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("ENTRY skipped: no qualifying call contract")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug(
            f"ENTRY submitted {selected.Symbol} exp {expiration} strike {selected.Strike}"
        )

    def _evaluate_option_exit(self, data: Slice):
        if self.held_contract is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            self.held_contract = None
            self.entry_price = None
            return

        if self.exit_order_id is not None:
            return

        quote_bar = data.QuoteBars.get(self.held_contract)
        if quote_bar is not None and quote_bar.Bid is not None and quote_bar.Ask is not None:
            bid = quote_bar.Bid.Close
            ask = quote_bar.Ask.Close

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.50 * self.entry_price:
                    self._submit_exit("profit target")
                    return

        expiry_date = self.held_contract.ID.Date.date()
        if (
            self.Time.time() == time(15, 45)
            and self._next_trading_day(self.Time.date()) == expiry_date
        ):
            self._submit_exit("pre-expiration time stop")

    def _handle_expiration_safety(self):
        if self.held_contract is None:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() < expiry_date:
            return

        self.no_entry_date = self.Time.date()
        if self.Portfolio[self.held_contract].Quantity != 0 and self.exit_order_id is None:
            self._submit_exit("expiration safety")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.equity_liquidation_order_id is not None:
            return

        ticket = self.MarketOrder(self.spy, -quantity)
        self.equity_liquidation_order_id = ticket.OrderId
        self.Debug(f"Unexpected SPY exercise/assignment position; liquidating {quantity}")

    def _submit_exit(self, reason: str):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        if self.exit_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
            if ticket is not None:
                ticket.Cancel("Replacing existing exit order")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"EXIT submitted {self.held_contract}: {reason}")

    def _has_option_holding(self) -> bool:
        for security in self.Securities.Values:
            if (
                security.Type == SecurityType.Option
                and self.Portfolio[security.Symbol].Invested
            ):
                return True
        return False

    def _next_trading_day(self, current_date):
        candidate = current_date + timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        for _ in range(10):
            candidate_datetime = datetime.combine(candidate, time.min)
            if exchange_hours.IsDateOpen(candidate_datetime):
                return candidate
            candidate += timedelta(days=1)

        return candidate

