        option.SetFilter(
            lambda universe: universe.Strikes(-1000, 1000)
            .Expiration(timedelta(0), timedelta(days=365))
        )
        self.option_symbol = option.Symbol

        self.closes = RollingWindow[float](21)
        self.pending_entry_signal = False

        self.entry_order_id = None
        self.exit_order_id = None
        self.held_contract = None
        self.entry_fill_price = None
        self.expiration_exit_date = None
        self.blocked_entry_dates = set()

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.closes.Add(bar.Close)

        if not self.closes.IsReady:
            return

        current_fast = sum(self.closes[i] for i in range(5)) / 5.0
        current_slow = sum(self.closes[i] for i in range(20)) / 20.0
        previous_fast = sum(self.closes[i] for i in range(1, 6)) / 5.0
        previous_slow = sum(self.closes[i] for i in range(1, 21)) / 20.0

        end_time = bar.EndTime.time()
        eligible_time = time(9, 45) <= end_time <= time(14, 30)

        if eligible_time and previous_fast <= previous_slow and current_fast > current_slow:
            self.pending_entry_signal = True

    def OnData(self, data):
        self.HandleUnexpectedSpyEquityPosition()
        self.HandleExpirationSafetyExit()
        self.HandleTimeStop()
        self.HandleProfitTarget(data)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.Time.date() in self.blocked_entry_dates:
            return

        if self.held_contract is not None or self.entry_order_id is not None:
            return

        if self.exit_order_id is not None:
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no SPY option chain in current Slice.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug("Entry skipped: invalid SPY price.")
            return

        current_date = self.Time.date()
        eligible_contracts = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and (contract.Expiry.date() - current_date).days >= 7
        ]

        if not eligible_contracts:
            self.Debug("Entry skipped: no call expiration at least 7 calendar days away.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in eligible_contracts)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in eligible_contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call strike at selected expiration.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                f"Entry submitted: {selected.Symbol} strike {selected.Strike} "
                f"expiry {selected.Expiry.date()}."
            )

    def HandleProfitTarget(self, data):
        if self.held_contract is None or self.entry_fill_price is None:
            return

        if self.exit_order_id is not None:
            return

        quote = data.QuoteBars.get(self.held_contract)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * 1.50:
            self.SubmitExit("profit target")

    def HandleTimeStop(self):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        expiry_date = self.held_contract.ID.Date.date()
        prior_trading_day = self.GetPriorTradingDay(expiry_date)

        if (
            self.Time.date() == prior_trading_day
            and self.Time.time() == time(15, 45)
            and self.expiration_exit_date != self.Time.date()
        ):
            self.expiration_exit_date = self.Time.date()
            self.SubmitExit("15:45 pre-expiration time stop")

    def HandleExpirationSafetyExit(self):
        if self.held_contract is None:
            return

        expiry_date = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry_date:
            self.blocked_entry_dates.add(self.Time.date())
            if self.exit_order_id is None:
                self.Debug(
                    f"Expiration safety handling: liquidating {self.held_contract}."
                )
                self.SubmitExit("expiration safety")

    def HandleUnexpectedSpyEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        open_spy_orders = self.Transactions.GetOpenOrders(self.spy)
        if not open_spy_orders:
            self.Debug(
                f"Unexpected SPY equity position ({quantity}) from exercise/assignment; "
                "liquidating immediately."
            )
            self.MarketOrder(self.spy, -quantity)

    def SubmitExit(self, reason):
        if self.held_contract is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            order_ticket = self.Transactions.GetOrderTicket(order.Id)
            if order_ticket is not None:
                order_ticket.Cancel("Replacing open exit order.")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(f"Exit submitted for {self.held_contract}: {reason}.")

    def GetPriorTradingDay(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event):
        if self.entry_order_id is not None and order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {self.held_contract} at {self.entry_fill_price:.2f}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None
                self.Debug(f"Entry order closed without fill: {order_event.Status}.")

        if self.exit_order_id is not None and order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice:.2f}."
                )
                self.exit_order_id = None
                self.held_contract = None
                self.entry_fill_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None
                self.Debug(f"Exit order closed without fill: {order_event.Status}.")

