        if self._no_entry_date == self.Time.date():
            return

        if self._held_contract is not None or self._entry_order_id is not None:
            return

        if self.Portfolio[self.spy].Invested:
            return

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Skipped entry: no current SPY price.")
            return

        chain = data.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no current SPY option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expiries = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Right == OptionRight.Call
                and contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expiries:
