            return

        if self._has_open_exit_order():
            return

        expiry_date = self._held_contract.ID.Date.date()
        if (
            self.Time.date() == expiry_date - timedelta(days=1)
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self.Debug(f"Time-stop exit: {self._held_contract}")
            self._submit_exit("time stop")
            return

