            return

        contract = self._current_contract(data, self._held_contract)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_price * 1.50:
            self.Debug(f"Profit-target exit: {self._held_contract}")
            self._submit_exit("profit target")

    def _current_contract(self, data: Slice, symbol: Symbol):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _submit_exit(self, reason: str):
        if self._held_contract is None:
            return

        for order in self.Transactions.GetOpenOrders(self._held_contract):
            self.Transactions.CancelOrder(order.Id, f"Replacing with {reason} market exit")

        quantity = self.Portfolio[self._held_contract].Quantity
        if quantity != 0:
            ticket = self.MarketOrder(self._held_contract, -quantity)
            if ticket is not None:
                self._exit_order_id = ticket.OrderId
                self.Debug(f"Exit submitted ({reason}): {self._held_contract}")

    def _has_open_exit_order(self):
        if self._held_contract is None:
            return False
        return len(self.Transactions.GetOpenOrders(self._held_contract)) > 0

    def _handle_unexpected_equity_position(self):
        if not self.Portfolio[self.spy].Invested:
            return

        if len(self.Transactions.GetOpenOrders(self.spy)) == 0:
            self.Debug("Unexpected SPY exercise/assignment position detected; liquidating.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if (
            self._entry_order_id is not None
            and orderEvent.OrderId == self._entry_order_id
        ):
            if orderEvent.Status == OrderStatus.Filled:
                self._entry_price = float(orderEvent.FillPrice)
                self._entry_order_id = None
                self.Debug(
                    f"Entry filled: {self._held_contract} at {self._entry_price:.2f}"
                )
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self.Debug(f"Entry failed: {self._held_contract}")
                self._entry_order_id = None
                self._held_contract = None
                self._entry_price = None

        if self._exit_order_id is not None and orderEvent.OrderId == self._exit_order_id:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self._held_contract}")
                self._held_contract = None
                self._entry_price = None
                self._exit_order_id = None
            elif orderEvent.Status in [OrderStatus.Canceled, OrderStatus.Invalid]:
                self._exit_order_id = None

